import math
from itertools import product

def gcd(a, b):
    return math.gcd(a, b)

def gcd3(a, b, c):
    return gcd(a, gcd(b, c))

def find_good_sets_size_3(limit=10000):
    good_numbers = set()

    # We enforce u1 < u2 < u3 to ensure unique sets U
    # Upper bound for u1: u1^3 < limit => u1 < limit^(1/3)
    max_u1 = int(limit**(1/3))

    for u1 in range(1, max_u1 + 1):
        # Upper bound for u2: u1*u2^2 < limit => u2 < sqrt(limit/u1)
        max_u2 = int((limit / u1)**0.5)
        for u2 in range(u1 + 1, max_u2 + 1):
            # Upper bound for u3: u1*u2*u3 < limit => u3 < limit/(u1*u2)
            max_u3 = int(limit / (u1 * u2))
            for u3 in range(u2 + 1, max_u3 + 1):

                # Condition 1: GCD must be 1
                if gcd3(u1, u2, u3) != 1:
                    continue

                # Condition 2: Divisibility requirements
                # u1 | u2*u3
                cond1 = (u2 * u3) % u1 == 0
                # u2 | u1*u3
                cond2 = (u1 * u3) % u2 == 0
                # u3 | u1*u2
                cond3 = (u1 * u2) % u3 == 0

                if cond1 and cond2 and cond3:
                    m = u1 * u2 * u3
                    good_numbers.add(m)

    return sorted(list(good_numbers))

