import math
import itertools

def gcd(a, b):
    return math.gcd(a, b)

def gcd_three(a, b, c):
    return gcd(a, gcd(b, c))

def check_good_set(u1, u2, u3):
    """Checks if {u1, u2, u3} is a good set."""
    # 1. GCD Condition
    if gcd_three(u1, u2, u3) != 1:
        return False

    # 2. Divisibility Condition
    # u1 | u2 * u3
    if (u2 * u3) % u1 != 0:
        return False
    # u2 | u1 * u3
    if (u1 * u3) % u2 != 0:
        return False
    # u3 | u1 * u2
    if (u1 * u2) % u3 != 0:
        return False

    return True

def find_good_numbers(max_u3):
    """Finds good numbers m = u1*u2*u3 up to a bound implied by max_u3."""
    good_numbers = set()
    # Iterate over u1 < u2 < u3
    for u1 in range(2, max_u3 + 1):
        for u2 in range(u1 + 1, max_u3 + 1):
            for u3 in range(u2 + 1, max_u3 + 1):
                if check_good_set(u1, u2, u3):
                    m = u1 * u2 * u3
                    good_numbers.add(m)

    return sorted(list(good_numbers))

# Increase the search bound significantly from the initial implied bound
# If we searched up to u3=50, the product m can be up to 50*49*48 = 117600.
# Let's set max_u3 = 50 to capture enough data.
MAX_U3 = 50
all_good_numbers = find_good_numbers(MAX_U3)

# Check the size of the found list
num_found = len(all_good_numbers)

# Extract the first 30 numbers, or all if fewer than 30
required_count = 30
results = all_good_numbers[:required_count]

# Report key findings
print(f"Total good numbers found with max(U)=50: {num_found}")
print(f"The first {min(required_count, num_found)} good numbers are:")
print(results)

if len(results) >= 20:
    print(f"The 20th smallest good number found is: {results[19]}")
else:
    print("Not enough good numbers found in this range to check the 20th one.")
